import { readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");
const source = join(root, "packages", "sandbox", "guest", "code-tools.mjs");
const target = join(root, "packages", "core", "src", "code-tools.generated.ts");

const script = readFileSync(source, "utf8");
const banner =
  "// AUTO-GENERATED by scripts/bundle-code-tools.mjs. Do not edit by hand.\n" +
  "// Source: packages/sandbox/guest/code-tools.mjs (the grep/glob helper the\n" +
  "// daemon runs inside the agent's computer). Regenerate with `pnpm skills:bundle`.\n";
writeFileSync(
  target,
  `${banner}export const CODE_TOOLS_SOURCE = ${JSON.stringify(script)};\n`,
);
console.log(
  `wrote ${target} (${(script.length / 1024).toFixed(1)} KiB source)`,
);
